function bake(gltf){let root=gltf.scene;root.updateMatrixWorld(true);let bounds=new T.Box3().setFromObject(root),size=bounds.getSize(new T.Vector3()),center=bounds.getCenter(new T.Vector3());let normalize=new T.Matrix4().makeScale(size.x>1e-5?1/size.x:1,size.y>1e-5?1/size.y:1,size.z>1e-5?1/size.z:1).multiply(new T.Matrix4().makeTranslation(-center.x,-bounds.min.y,-center.z));let groups=new Map();root.traverse(o=>{if(!o.isMesh)return;let materials=Array.isArray(o.material)?o.material:[o.material];for(let material of materials){let geo=o.geometry.clone();if(materials.length>1)continue;geo.applyMatrix4(o.matrixWorld);geo.applyMatrix4(normalize);if(geo.index)geo=geo.toNonIndexed();for(let key of Object.keys(geo.attributes))if(!['position','normal','uv'].includes(key))geo.deleteAttribute(key);if(!geo.attributes.uv)geo.setAttribute('uv',new T.BufferAttribute(new Float32Array(geo.attributes.position.count*2),2));if(!groups.has(material.uuid))groups.set(material.uuid,{material,geos:[]});groups.get(material.uuid).geos.push(geo)}});return{parts:[...groups.values()].map(({material,geos})=>({material,geometry:mergeGeometries(geos,false)})),size}}
function texture(kind){let c=document.createElement('canvas');c.width=c.height=128;let x=c.getContext('2d'),image=x.createImageData(128,128);for(let y=0;y<128;y++)for(let q=0;q<128;q++){let i=(y*128+q)*4,n=Math.random();let base=kind==='fabric'?185+Math.sin(q*Math.PI)*14+Math.cos(y*Math.PI)*14+n*45:kind==='fur'?190+Math.sin(q*.2+y*.9)*20+n*35:kind==='concrete'?175+n*70:kind==='skin'?208+n*35:160+n*75;image.data.set([base,base,base,255],i)}x.putImageData(image,0,0);let t=new T.CanvasTexture(c);t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(kind==='concrete'?4:1,kind==='concrete'?10:1);t.colorSpace=T.SRGBColorSpace;t.anisotropy=4;return t}
