for(let mesh of this.carBatches||[]){let instances=mesh.userData.instances;for(let i=0;i<instances.length;i++){let c=this.w.traffic[i],x=c.axis==='x'?c.offset:c.lane+c.dir*4.5,z=c.axis==='z'?c.offset:c.lane+c.dir*4.5,visible=Math.abs(x-this.w.plan.river)>39||[-450,-150,150,450].some(v=>Math.abs(z-v)<10);dummy.position.set(x,visible?-.4:-30,z);dummy.rotation.set(0,c.axis==='x'?(c.dir>0?Math.PI/2:-Math.PI/2):(c.dir>0?0:Math.PI),0);dummy.scale.set(1.8,1.65,4.3);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);instances[i].record.x=x;instances[i].record.z=z}mesh.instanceMatrix.needsUpdate=true;mesh.computeBoundingSphere()}
